def right_angle_triangle(a, b, c):
    # Validate input values to ensure they are positive integers
    if a <= 0 or b <= 0 or c <= 0:
        return False

    # Check if the three sides can form a triangle by applying the triangle inequality theorem
    if a + b <= c or a + c <= b or b + c <= a:
        return False

    # Check if one of the angles is a right angle by applying the Pythagorean theorem
    sides = [a, b, c]
    sides.sort()
    if sides[0]**2 + sides[1]**2 == sides[2]**2:
        return True
